const M=BookMap,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='bookmap-demo-v1';let state=structuredClone(M.seed),page='map',selected='c1',category='全部',query='',shelf='all';try{const s=localStorage.getItem(key);if(s)state=M.validate(JSON.parse(s))}catch{setTimeout(()=>toast('本地备份异常，已载入演示数据'),200)}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}function mutate(fn){const next=structuredClone(state),result=fn(next);M.validate(next);try{localStorage.setItem(key,JSON.stringify(next))}catch{throw Error('无法保存，请检查浏览器存储权限')}state=next;render();return result}const cab=id=>M.cabinets.find(c=>c.id===id),cabName=id=>cab(id)?.name||'示例书柜';const btn=(action,text,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;const cover=b=>`<div class="book-cover" style="--cover:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#718368'};--text:${/^#[0-9a-f]{6}$/i.test(b.text)?b.text:'#fff8e5'}"><small>A READING JOURNEY</small><span>${esc(b.title)}</span><small>书旅 MAP / 循环藏书</small></div>`;function modal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal()}function close(){$('#modal').close()}function heading(title,sub,extra=''){return `<div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${extra}</div>`}function inventory(c){return state.books.filter(b=>b.cabinet===c&&M.available(state,b)).length}function cards(){let list=state.books.filter(b=>M.available(state,b)&&(shelf==='all'||b.cabinet===selected)&&(category==='全部'||b.category===category)&&(!query||(b.title+b.author).includes(query)));return list.map(b=>`<article class="book-card"><div class="cover-space">${cover(b)}</div><h3>${esc(b.title)}</h3><div class="sub">${esc(b.author)} · ${esc(b.condition)}</div><div class="sub">${esc(cabName(b.cabinet).split(' · ')[0])}</div><div class="bottom"><span class="price">${b.coins} <small>书币</small></span>${btn('book','查看 ↗',b.id)}</div></article>`).join('')||'<div class="empty">还没找到这本书，换个关键词或书柜试试吧。</div>'}
function render(){$('#balance').textContent=state.balance;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));let h='';if(page==='map'){const c=cab(selected);h=`<section class="hero"><div><span class="eyebrow">A NEW CHAPTER, A NEW JOURNEY</span><h1>你的下一本好书，<br>也许<em>就在转角。</em></h1><p>在身边的书柜里，遇见一本读过的好书。<br>让故事在你我之间，开始下一段旅行。</p>${btn('deposit','＋ 投递旧书，赚书币','','primary')}<div class="metrics"><span><b>3</b>校园书柜</span><span><b>${state.books.filter(b=>M.available(state,b)).length}</b>本书待相遇</span><span><b>${state.deposits.filter(d=>d.status==='approved').length}</b>次循环完成</span></div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="hero-book">故事<br>未完</div><div class="hero-book second">READ<br>AGAIN</div><div class="leaf">❋</div></div></section>`;h+=heading('沿着地图，遇见好书','选择一个书柜，看看故事停在哪一站', '<span class="badge">虚构校园示意图</span>');h+=`<div class="grid-map"><div class="map" aria-label="校园书柜示意图"><span class="map-tools">⌖ 青禾大学 · 非真实定位</span><div class="park">梧桐绿地</div><div class="lake">青禾湖</div><div class="building b1">图书馆</div><div class="building b2">生活区</div><div class="building b3">教学楼</div>${M.cabinets.map((c,i)=>`<button class="pin ${c.id===selected?'selected':''}" style="left:${c.x}%;top:${c.y}%;transform:translateX(-50%)" data-action="cabinet" data-id="${c.id}">⌑ ${['梧桐','微光','河岸'][i]} · ${inventory(c.id)} 本</button>`).join('')}<span class="map-label">距离为固定示例 · 点击标签切换书柜</span></div><div class="cabinet"><span class="badge ${c.open?'':'orange'}">${c.open?'● 正常营业':'● 维护中'}</span><h3>${c.name}</h3><p class="sub">⌖ ${c.place} · ${c.distance}</p><div class="details"><span><b>${inventory(c.id)}</b>可借取藏书</span><span><b>${c.capacity-state.deposits.filter(d=>d.cabinet===c.id&&d.status==='pending').length}</b>空余投递格</span></div><p class="sub">开放时间：${c.hours}</p><p class="sub">柜内图书均为模拟质检通过状态</p>${btn('shelf','查看本柜藏书 →',c.id,'wide primary')}${btn('deposit','投递到此书柜',c.id,'wide')}</div></div>`;h+=heading(shelf==='all'?'这些好书，等你翻开':'本柜藏书 · '+c.name,'借阅仅需 10 书币押币，14 天内归还退还',`<div class="searchbar"><input id="search" aria-label="搜索书名或作者" placeholder="搜索书名 / 作者" value="${esc(query)}"></div>`);h+=`<div class="filters">${['全部','文学','悬疑','社科','成长'].map(t=>`<button data-action="category" data-id="${t}" class="${category===t?'active':''}">${t}</button>`).join('')}${shelf!=='all'?btn('allbooks','返回全部藏书'):''}</div><div class="books" id="book-list">${cards()}</div>`}
if(page==='boxes'){h=heading('把下一本书，交给惊喜','主题明确，书名未知。每个盲盒 1 本书，全部为纯书币演示兑换。');h+='<div class="note">示例规则：每个主题包含 3 种候选书，等概率随机抽取。无现金支付，不支持书币提现；兑换前可查看候选清单。</div><div class="box-grid">'+M.boxes.map(x=>`<article class="box-card"><div class="box-art" style="--box:${x.color};--tint:${x.tint}"><div class="parcel">${x.name.slice(0,2)}<br>？</div></div><div class="box-info"><span class="eyebrow">A SURPRISE BETWEEN PAGES</span><h3>${x.name}</h3><p class="sub">${x.desc}</p><div class="btn-row"><span class="price">${x.coins} 书币</span>${btn('box','看看主题 →',x.id)}</div></div></article>`).join('')+'</div>';h+=heading('一份惊喜，也是一场循环','盲盒图书来自模拟回收书池，领取柜默认为图书馆梧桐书柜。');h+='<div class="hint-card">体验目标：用阅读主题降低选择成本，用书币推动旧书循环。真实运营需要单独验证库存、抽取规则与成本。</div>'}
if(page==='coins'){h=`<section class="coin-hero"><div><span class="eyebrow" style="color:#c4d3b9">YOUR READING WALLET</span><p>我的书币余额</p><h1>${state.balance}<small style="font-size:14px;margin-left:10px">书币</small></h1><p>每一次分享，都值得被记录。</p>${btn('deposit','投递旧书赚书币 →')}</div><div class="coin-icon">◉</div></section><div class="note">书币为课程演示积分，无现金价值。投递质检通过后发放；借阅扣 10 押币，归还时退还，超期每天扣 1 押币，最多扣完押币。</div>`;h+=heading('书币足迹','每一笔收入与支出，都有来处');h+=state.ledger.map(l=>`<div class="row"><span class="group-icon" style="height:38px;width:38px;font-size:20px">◉</span><div class="grow"><h3>${esc(l.text)}</h3><div class="sub">${esc(l.time)}</div></div><span class="${l.amount>=0?'positive':'negative'}">${l.amount>0?'+':''}${l.amount}</span></div>`).join('')}
if(page==='groups'){h=heading('因为一本书，遇见同路人','按兴趣自由加入，聊阅读，也聊生活。');h+='<div class="hero" style="min-height:150px"><div><span class="eyebrow">BETTER TOGETHER</span><h1 style="font-size:26px">阅读可以独处，<br>共鸣不必孤单。</h1><p>以书为起点，找到愿意认真听你分享的人。</p></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="leaf" style="right:60px;font-size:110px">♧</div></div></div>';h+=M.groups.map(g=>`<article class="row"><div class="group-icon">${g.icon}</div><div class="grow"><h3>${g.name} <span class="badge">${state.groups.includes(g.id)?'已加入':g.members+' 位书友（示例）'}</span></h3><div class="sub">${g.tag}</div><p class="sub">${g.desc}</p></div>${state.groups.includes(g.id)?btn('chat','进入讨论',g.id,'primary'):btn('join','＋ 加入小组',g.id)}</article>`).join('');h+='<div class="note">群聊仅在本浏览器模拟，没有真实用户或消息发送。成员数为示例，加入记录与自己发布的内容会在本机保存。</div>'}
if(page==='me'){const borrowed=state.orders.filter(o=>o.status==='borrowed');h=`<section class="profile"><div class="avatar">☺</div><div><span class="eyebrow">A READER ON THE ROAD</span><h2>青禾读者</h2><div class="sub">演示账号 · 阅读偏好：文学 / 成长</div><span class="badge">信誉积分 100 · 示例</span></div></section><div class="profile-stats"><div><span class="sub">正在借阅</span><strong>${borrowed.length}<small>/3</small></strong></div><div><span class="sub">投递通过</span><strong>${state.deposits.filter(d=>d.status==='approved').length}</strong></div><div><span class="sub">加入小组</span><strong>${state.groups.length}</strong></div></div>`;h+=heading('我的书架与领取凭证','借阅、兑换、归还，都在这里');h+=state.orders.length?state.orders.map(o=>`<article class="row"><div class="grow"><h3>${esc(o.title)} <span class="badge">${({borrowed:'借阅中',bought:'已兑换',returned:'已归还',box:'盲盒已揭晓'})[o.status]}</span></h3><div class="sub">${esc(cabName(o.cabinet))}${o.status==='borrowed'?' · 应还 '+o.due:''}</div>${o.status!=='returned'?`<div class="sub">模拟取书码：<strong>${esc(o.code)}</strong>（无开柜能力）</div>`:`<div class="sub">已归还 · 超期扣押币 ${o.fee||0}</div>`}</div>${o.status==='borrowed'?btn('return','模拟归还',o.id):''}</article>`).join(''):'<div class="empty">你的书架还是空的。去地图上发现第一本好书吧。</div>';h+=heading('旧书投递进度','审核入口仅用于课程演示，真实服务应由运营人员操作');h+=state.deposits.length?state.deposits.map(d=>`<div class="row"><div class="grow"><h3>${esc(d.title)}</h3><div class="sub">${esc(d.condition)} · 预估 ${d.reward} 书币 · ${esc(cabName(d.cabinet))}</div><span class="badge">${({pending:'待人工质检（模拟）',approved:'已通过 · 书币已到账',rejected:'未通过 · 请联系工作人员取回'})[d.status]}</span></div>${d.status==='pending'?btn('review','模拟质检',d.id):''}</div>`).join(''):'<div class="empty">投递一本闲置书，让它开始新的旅程。</div>';h+=heading('数据与演示设置','仅保存于当前浏览器，建议导出备份');h+=`<div class="btn-row">${btn('export','导出数据备份')}<button data-action="import">导入备份</button>${btn('reset','重置示例数据')}</div><input id="import-file" type="file" accept="application/json" hidden>`}
$('#screen').innerHTML=h}
function bookModal(id){const b=state.books.find(b=>b.id===id);if(!b)return;modal('一本书的下一站',`<div class="modal-book">${cover(b)}<div><h3>${esc(b.title)}</h3><p class="sub">${esc(b.author)} · ${esc(b.category)}</p><span class="badge">${esc(b.condition)}</span><p class="sub">${esc(b.tag||'书友分享藏书')}</p><p class="price">${b.coins} 书币 <span class="sub">参考售价 ¥${b.price}（不支持现金结算）</span></p></div></div><div class="hint-card">所在书柜：${esc(cabName(b.cabinet))}<br>借阅 14 天，押币 10；最多同时借 3 本。超期从押币中每天扣 1，最多扣 10。</div>${!cab(b.cabinet).open?'<p class="error">书柜维护中，暂不可借取。</p>':!M.available(state,b)?'<p class="error">这本书已被领取。</p>':`<div class="btn-row">${btn('checkout','借阅 · 10 押币',b.id,'primary')}${btn('buy','书币购书 · '+b.coins,b.id)}</div>`}`)}
function depositModal(preselect){const options=M.cabinets.filter(c=>c.open).map(c=>`<option value="${c.id}" ${c.id===(preselect||selected)?'selected':''}>${c.name}</option>`).join('');modal('让闲置好书，开始新旅程',`<p class="sub">扫描 / OCR 为模拟识别；请手动核对书名、作者与品相。提交后需要模拟人工质检，书币才会到账。</p><form id="deposit-form"><button type="button" data-action="ocr">▧ 模拟扫描示例书籍</button><label>书名<input name="title" required maxlength="60" placeholder="输入你想分享的书名"></label><label>作者<input name="author" required maxlength="40"></label><label>主题分类<select name="category"><option>文学</option><option>悬疑</option><option>社科</option><option>成长</option></select></label><label>品相<select name="condition" id="condition"><option>九成新</option><option>全新</option><option>八五新</option></select></label><div class="sub">全新：无阅读痕迹；九成新：轻微使用；八五新：少量划线。缺页、霉变、盗版不接收。</div><label>投递书柜<select name="cabinet">${options}</select></label><div class="note">预估回收奖励 <b id="estimate">25</b> 书币 · 最终以质检结果为准</div><label><input type="checkbox" name="agree" required>确认书籍无缺页、霉变，且为合法正版</label><p id="form-error" class="error" role="alert"></p><button class="primary wide" type="submit">确认模拟投递</button></form>`)}
function boxModal(id){const x=M.boxes.find(x=>x.id===id);modal(x.name+' · 主题盲盒',`<p>${x.desc}</p><div class="hint-card">每盒 1 本，候选书目：<br>${x.pool.map(esc).join(' / ')}<br>每种概率 1/3，可能与已读书重复。</div><p>需 ${x.coins} 书币 · 当前余额 ${state.balance}</p><p class="sub">确认后立即扣除书币并揭晓，领取地点：图书馆梧桐书柜。仅为本地演示，无真实交易。</p>${btn('redeem','确认兑换并揭晓',id,'primary wide')}`)}
function chatModal(id){const g=M.groups.find(g=>g.id===id);modal(g.name,`<p class="sub">本地模拟讨论 · 不会发送给真实用户</p><div>${(state.messages[id]||[]).map(m=>`<div class="message ${m.name==='我'?'mine':''}"><small>${esc(m.name)}</small>${esc(m.text)}</div>`).join('')}</div><form id="chat-form" data-group="${id}"><label>分享你的阅读想法<input name="text" required maxlength="300" placeholder="最近哪句话打动了你？"></label><button type="submit" class="primary wide">发布到本地讨论</button></form>${btn('leave','退出小组',id,'wide')}`)}
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.closest('#nav')){page=b.dataset.page;render();return}const a=b.dataset.action,id=b.dataset.id;if(!a)return;try{if(a==='page'){page=b.dataset.page;render()}if(a==='cabinet'){selected=id;render()}if(a==='shelf'){selected=id;shelf='cabinet';render();$('#book-list').scrollIntoView({behavior:'smooth',block:'center'})}if(a==='allbooks'){shelf='all';render()}if(a==='category'){category=id;render()}if(a==='book')bookModal(id);if(a==='deposit')depositModal(id);if(a==='ocr'){const f=$('#deposit-form');f.elements.title.value='小王子';f.elements.author.value='圣埃克苏佩里';toast('已填入模拟识别结果，请核对后提交')}if(a==='checkout'||a==='buy'){const o=mutate(s=>M.checkout(s,id,a==='buy'?'buy':'borrow'));modal('已生成模拟领取凭证',`<span class="badge">${a==='buy'?'已扣除购书书币':'已扣除 10 押币'}</span><h3>${esc(o.title)}</h3><p>${esc(cabName(o.cabinet))}</p><h1 style="letter-spacing:5px">${o.code}</h1><p class="sub">此码为演示凭证，不会开启真实书柜。${a==='checkout'?'请于 '+o.due+' 前归还。':''}</p>${btn('mybooks','查看我的书架','','primary wide')}`)}if(a==='mybooks'){close();page='me';render()}if(a==='return'){modal('确认模拟归还',`<p>确认已将书放回原书柜？完成后图书重新可借，按规则退还押币。</p><p class="sub">本次不会操作真实柜体。</p>${btn('return-confirm','确认归还',id,'primary wide')}`)}if(a==='return-confirm'){const o=mutate(s=>M.returnBook(s,id));close();toast('归还完成，退回 '+(o.deposit-o.fee)+' 书币')}if(a==='box')boxModal(id);if(a==='redeem'){const o=mutate(s=>M.redeem(s,id));modal('你的下一段阅读旅程',`<span class="eyebrow">SURPRISE, REVEALED.</span><h1>《${esc(o.title)}》</h1><p>来自「${esc(o.theme)}」主题盲盒</p><div class="hint-card">领取柜：${esc(cabName(o.cabinet))}<br>模拟取书码：${o.code}</div>${btn('mybooks','收进我的书架','','primary wide')}`)}if(a==='join'){mutate(s=>{if(!s.groups.includes(id))s.groups.push(id)});toast('已加入小组，欢迎分享阅读')}if(a==='chat')chatModal(id);if(a==='leave'){mutate(s=>s.groups=s.groups.filter(g=>g!==id));close();toast('已退出小组')}if(a==='review'){const d=state.deposits.find(d=>d.id===id);modal('模拟后台 · 书籍质检',`<p>《${esc(d.title)}》 · ${esc(d.condition)}</p><p class="sub">仅用于演示运营审批。真实系统应限制为运营人员，并记录品相、正版核查和消毒结果。</p><div class="hint-card">通过后：发放 ${d.reward} 书币，书籍上架。<br>拒绝后：不发书币，保留记录并提示取回。</div><div class="btn-row">${btn('approve','质检通过',id,'primary')}${btn('reject','拒绝上架',id)}</div>`)}if(a==='approve'||a==='reject'){mutate(s=>M.review(s,id,a==='approve'));close();toast(a==='approve'?'质检通过，奖励已到账，书籍已上架':'已拒绝上架，请按记录取回书籍')}if(a==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=u;link.download='书旅Map-备份.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}if(a==='import')$('#import-file').click();if(a==='reset')modal('重置演示数据',`<p>这会替换当前浏览器中的所有演示记录。建议先导出备份。</p>${btn('reset-confirm','确认重置','','primary wide')}`);if(a==='reset-confirm'){mutate(s=>{Object.assign(s,structuredClone(M.seed))});close();toast('已恢复初始示例')}}catch(err){toast(err.message)}});
$('#close').onclick=close;document.body.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value.trim();$('#book-list').innerHTML=cards()}});document.body.addEventListener('change',async e=>{if(e.target.id==='condition')$('#estimate').textContent=M.estimate(e.target.value);if(e.target.id==='import-file'){try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('文件超过2MB');const next=M.validate(JSON.parse(await f.text()));window.pendingImport=next;modal('确认导入备份',`<p>备份包含 ${next.books.length} 本藏书、${next.orders.length} 条领取记录，余额 ${next.balance} 书币。导入将覆盖当前演示数据。</p>${btn('import-confirm','确认覆盖导入','','primary wide')}`)}catch(err){toast('导入失败：'+err.message)}e.target.value=''}});document.body.addEventListener('click',e=>{if(e.target.closest('[data-action="import-confirm"]')){try{mutate(s=>Object.assign(s,window.pendingImport));window.pendingImport=null;close();toast('导入成功')}catch(err){toast(err.message)}}});document.body.addEventListener('submit',e=>{if(e.target.id==='deposit-form'){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));const r=mutate(s=>M.deposit(s,d));modal('投递完成 · 等待质检',`<span class="badge">模拟柜门已关闭</span><h3>《${esc(r.title)}》的旅程即将开始</h3><p>预估奖励 ${r.reward} 书币，质检通过后到账。</p><p class="sub">消毒设备、称重及开柜均未接入真实硬件。本演示不会实际消毒。</p>${btn('mybooks','前往个人中心模拟质检','','primary wide')}`)}catch(err){$('#form-error').textContent=err.message}}if(e.target.id==='chat-form'){e.preventDefault();try{const text=new FormData(e.target).get('text').trim(),id=e.target.dataset.group;if(!text)return;mutate(s=>{if(!s.groups.includes(id))throw Error('请先加入小组');s.messages[id]??=[];s.messages[id].push({name:'我',text:text.slice(0,300)})});chatModal(id)}catch(err){toast(err.message)}}});render();
